import { TagInput } from '@/lib/designsystem';
import { useState } from 'react';

function TagSelector() {
  const [selectedTags, setSelectedTags] = useState<string[]>([]);

  return (
    <TagInput
      id="categories"
      label="Categories"
      availableTags={[
        { id: '1', name: 'Technology' },
        { id: '2', name: 'Design' },
        { id: '3', name: 'Marketing' },
      ]}
      selectedTags={selectedTags}
      onChange={setSelectedTags}
      helperText="Select categories for your content"
    />
  );
}

import { useState, FormEvent } from 'react';
import { TagInput, Button } from '@/lib/designsystem';

function ArticleForm() {
  const [title, setTitle] = useState('');
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});

  const availableTags = [
    { id: 'tech', name: 'Technology' },
    { id: 'design', name: 'Design' },
    { id: 'business', name: 'Business' },
  ];

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();

    // Validate form
    const newErrors: { [key: string]: string } = {};

    if (!title.trim()) {
      newErrors.title = 'Title is required';
    }

    if (selectedTags.length === 0) {
      newErrors.tags = 'At least one tag is required';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    // Submit form...
    console.log({ title, tags: selectedTags });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <label htmlFor="title" className="block text-sm font-medium">
          Title
        </label>
        <input
          id="title"
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          className="w-full rounded-md border p-2"
        />
        {errors.title && <p className="text-sm text-red-500">{errors.title}</p>}
      </div>

      <TagInput
        id="tags"
        label="Tags"
        availableTags={availableTags}
        selectedTags={selectedTags}
        onChange={setSelectedTags}
        error={errors.tags}
        helperText="Select at least one tag for your article"
        required
      />

      <Button type="submit">Submit Article</Button>
    </form>
  );
}
